using System.Reflection;
using NUnit.Framework;
using TMPro;
using UnityEditor;
using UnityEngine;
namespace BeeHarvest.Tests {
 public sealed class NavigationBarAnimationTests {
  GameObject root;MainMenuNavigationBarView view;
  static float Center(RectTransform rect)=>(rect.anchorMin.x+rect.anchorMax.x)*.5f;
  void Tick(float delta){var method=typeof(MainMenuNavigationBarView).GetMethod("Tick");Assert.IsNotNull(method,"Navigation transition needs the runtime frame step");method.Invoke(view,new object[]{delta});}
  [SetUp] public void Setup(){root=new GameObject("NavigationFixture",typeof(RectTransform));((RectTransform)root.transform).sizeDelta=new Vector2(750,1334);view=root.AddComponent<MainMenuNavigationBarView>();var selection=new GameObject("Selection",typeof(RectTransform));selection.transform.SetParent(root.transform,false);view.Selection=(RectTransform)selection.transform;view.Icons=new RectTransform[3];view.Labels=new TMP_Text[3];for(int i=0;i<3;i++){var icon=new GameObject("Icon"+i,typeof(RectTransform));icon.transform.SetParent(root.transform,false);view.Icons[i]=(RectTransform)icon.transform;var label=new GameObject("Label"+i,typeof(RectTransform),typeof(TextMeshProUGUI));label.transform.SetParent(root.transform,false);view.Labels[i]=label.GetComponent<TMP_Text>();view.Labels[i].font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/Sprites/UI/Fonts/FredokaBoldSDF.asset");}view.ValidateBindings();view.Render(MainMenuTab.Home);}
  [TearDown] public void Cleanup(){Object.DestroyImmediate(root);}
  [Test] public void ClickPreservesStartThenMovesPlateIconsAndLabelsTogether(){float start=Center(view.Selection);view.Render(MainMenuTab.Shop);Assert.AreEqual(start,Center(view.Selection),.0001f,"Tab changes must animate rather than teleport");Tick(.1f);Assert.That(Center(view.Selection),Is.InRange(.167f,.499f));Assert.That(view.Icons[0].sizeDelta.x,Is.InRange(110.1f,141.9f));Assert.That(view.Icons[1].sizeDelta.x,Is.InRange(110.1f,141.9f));Assert.That(view.Labels[0].alpha,Is.InRange(.001f,.999f));Assert.That(view.Labels[1].alpha,Is.InRange(.001f,.999f));Tick(.15f);Assert.AreEqual(1f/6,Center(view.Selection),.0001f);Assert.AreEqual(1f/3,view.Selection.anchorMax.x-view.Selection.anchorMin.x,.0001f);Assert.AreEqual(142,view.Icons[0].sizeDelta.x,.001f);Assert.AreEqual(126,view.Icons[0].anchoredPosition.y,.001f);Assert.AreEqual(110,view.Icons[1].sizeDelta.x,.001f);Assert.AreEqual(75,view.Icons[1].anchoredPosition.y,.001f);Assert.AreEqual(1,view.Labels[0].alpha);Assert.IsFalse(view.Labels[1].gameObject.activeSelf);}
  [Test] public void RapidRetargetStartsAtTheCurrentIntermediatePose(){view.Render(MainMenuTab.Shop);Tick(.09f);float center=Center(view.Selection),size=view.Icons[0].sizeDelta.x,alpha=view.Labels[0].alpha;view.Render(MainMenuTab.Gallery);Assert.AreEqual(center,Center(view.Selection),.0001f);Assert.AreEqual(size,view.Icons[0].sizeDelta.x,.001f);Assert.AreEqual(alpha,view.Labels[0].alpha,.001f);Tick(.25f);Assert.AreEqual(5f/6,Center(view.Selection),.0001f);Assert.AreEqual(1,view.Labels[2].alpha);Assert.AreEqual(0,view.Labels[0].alpha);}
  [Test] public void RepeatedTargetDoesNotRestartAndInvalidTimeDoesNotAdvance(){view.Render(MainMenuTab.Shop);Tick(.12f);float center=Center(view.Selection);view.Render(MainMenuTab.Shop);Tick(0);Tick(-1);Tick(float.NaN);Tick(float.PositiveInfinity);Assert.AreEqual(center,Center(view.Selection),.0001f);Tick(.13f);Assert.AreEqual(1f/6,Center(view.Selection),.0001f);Assert.AreEqual(1,view.Labels[0].alpha);}
  [Test] public void BackgroundCompletesPendingPresentationBeforeResume(){view.Render(MainMenuTab.Gallery);Tick(.08f);typeof(MainMenuNavigationBarView).GetMethod("OnApplicationPause",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(view,new object[]{true});Assert.AreEqual(5f/6,Center(view.Selection),.0001f);Assert.AreEqual(1,view.Labels[2].alpha);Tick(.2f);Assert.AreEqual(5f/6,Center(view.Selection),.0001f);}
 }
}
